import {hopfAtlasAt} from '../../math/sonic/hopfAtlas.js'
import {clipSpectralTriangle} from './spectralCurveClip.js'
import {analyticHopfSection} from './analyticSection.js'

/** Mesh the implicit trace=0 sheet as a local graph, then clip by det>=0.
 * A vertex generated by clipping is reprojected onto trace=0, rather than
 * interpolating its tau coordinate between different z slices.
 */
export function hopfImplicitSurfaceMesh(p,{tauMin=-1,tauMax=1,YMin=-6,YMax=6,side='minus',nTau=42,nZ=100,zcMin=-.999,zcMax=.999,clipDet=true}={}){
  const positions=[],indices=[]
  const eps=1e-11
  const nY=Math.max(96,nTau)
  const zs=Array.from({length:nZ+1},(_,j)=>zcMin+(zcMax-zcMin)*(1-Math.cos(Math.PI*j/nZ))/2)
  const sections=zs.map(z=>{
    return analyticHopfSection(z,p,side)
  })
  const graph=(s,u,useTau)=>{
    if(!s)return null
    const tau=useTau?(-s.b*u-s.c)/s.a:u
    const Y=useTau?u:(-s.a*u-s.c)/s.b
    if(!Number.isFinite(tau)||!Number.isFinite(Y))return null
    const free=s.useTau?Y:tau
    const det=s.determinant(free)
    return Number.isFinite(det)?{p:[tau,Y,s.z],d:det}:null
  }
  // Use ONE chart for both ends of each strip. Switching charts between
  // adjacent sections used to discard the entire strip, leaving vertical seams.
  // The dominant coefficient at the strip midpoint avoids unstable division.
  const interpolate=(a,b,t)=>{
    const z=a.p[2]+t*(b.p[2]-a.p[2])
    const h0=hopfAtlasAt(0,0,z,p,side),ht=hopfAtlasAt(1,0,z,p,side),hy=hopfAtlasAt(0,1,z,p,side)
    if([h0,ht,hy].some(h=>h.kind!=='regular'))return null
    const A=ht.trace-h0.trace,B=hy.trace-h0.trace,C=h0.trace
    const Y=a.p[1]+t*(b.p[1]-a.p[1]),tau=a.p[0]+t*(b.p[0]-a.p[0])
    const q=Math.abs(A)>=Math.abs(B)?[(-C-B*Y)/A,Y,z]:[tau,(-C-A*tau)/B,z]
    const h=hopfAtlasAt(...q,p,side)
    return h.kind==='regular'?{p:q,d:h.det}:null
  }
  const clip=(poly,fn)=>{
    const out=[]
    for(let i=0;i<poly.length;i++){
      const a=poly[i],b=poly[(i+1)%poly.length],fa=fn(a),fb=fn(b)
      if(fa>=0)out.push(a)
      if((fa>=0)!==(fb>=0)){
        let lo=0,hi=1,fl=fa,mid=null
        for(let j=0;j<22;j++){
          const t=(lo+hi)/2
          mid=interpolate(a,b,t)
          if(!mid)break
          const fm=fn(mid)
          if((fm>=0)===(fl>=0)){lo=t;fl=fm}else hi=t
        }
        if(mid)out.push(mid)
      }
    }
    return out
  }
  const emitPolygon=tri=>{
    if(tri.some(v=>!v))return
    let poly=tri
    for(const fn of [v=>v.p[0]-tauMin,v=>tauMax-v.p[0],v=>v.p[1]-YMin,v=>YMax-v.p[1],]){
      poly=clip(poly,fn)
      if(poly.length<3)return
    }
    for(let i=1;i+1<poly.length;i++){
      const vs=[poly[0],poly[i],poly[i+1]]
      if(vs.some(v=>!v||!v.p.every(Number.isFinite)))continue
      const a=vs[0].p,b=vs[1].p,c=vs[2].p
      const u=b.map((x,j)=>x-a[j]),v=c.map((x,j)=>x-a[j])
      const cross=[u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]]
      if(cross.reduce((s,x)=>s+x*x,0)<1e-24)continue
      const base=positions.length/3
      positions.push(...a,...b,...c);indices.push(base,base+1,base+2)
    }
  }
  const emit=tri=>{
    if(!clipDet){emitPolygon(tri);return}
    if(tri.some(v=>!v))return
    const input=tri.map(v=>({...v,det:v.d}))
    const fragments=clipSpectralTriangle(input,(a,b,t)=>{
      const q=interpolate(a,b,t)
      return q?{...q,det:q.d}:null
    },{depth:2})
    for(const fragment of fragments)emitPolygon(fragment)
  }
  // A single globally regular graph eliminates the artificial seams created
  // when neighboring strips choose different dependent coordinates.
  // Only use it when its denominator stays uniformly away from zero.
  const validSections=sections.filter(Boolean)
  const globalTauGraph=validSections.length===sections.length &&
    validSections.every(s=>Math.abs(s.a)>eps*Math.max(1,Math.abs(s.b),Math.abs(s.c)))
  const globalYGraph=!globalTauGraph && validSections.length===sections.length &&
    validSections.every(s=>Math.abs(s.b)>eps*Math.max(1,Math.abs(s.a),Math.abs(s.c)))
  for(let j=0;j<nZ;j++){
    const s=sections[j],t=sections[j+1]
    if(!s||!t)continue
    const midA=(s.a+t.a)/2,midB=(s.b+t.b)/2
    const useTau=globalTauGraph ? true : globalYGraph ? false : Math.abs(midA)*(tauMax-tauMin)>=Math.abs(midB)*(YMax-YMin)
    if(useTau ? Math.min(Math.abs(s.a),Math.abs(t.a))<eps : Math.min(Math.abs(s.b),Math.abs(t.b))<eps)continue
    const min=useTau?YMin:tauMin,max=useTau?YMax:tauMax
    for(let i=0;i<nY;i++){
      const u=min+(max-min)*i/nY,v=min+(max-min)*(i+1)/nY
      const a=graph(s,u,useTau),b=graph(s,v,useTau),c=graph(t,v,useTau),d=graph(t,u,useTau)
      emit([a,b,c]);emit([a,c,d])
    }
  }
  return {positions,indices}
}
